from __future__ import annotations

import shutil
from pathlib import Path
from urllib.parse import urljoin
from urllib.request import pathname2url

from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_CONTENT_TYPE,
    RECORDING_FILE_EXTENSION,
)
from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingReference,
    _safe_key_part,
)
from rasa.core.config.available_endpoints import RecordingConfig


class LocalRecordingStorage:
    """Write call recordings to a configured local directory."""

    def __init__(self, config: RecordingConfig) -> None:
        if config.local is None:
            raise ValueError(
                "Local recording storage requires recordings.local config."
            )
        self._directory = Path(config.local.path).expanduser().resolve()

    def upload(
        self, source: Path, conversation_id: str, call_id: str
    ) -> RecordingReference:
        """Copy the recording into the configured local directory.

        Args:
            source: Path to the encoded recording file.
            conversation_id: Conversation identifier used in the filename.
            call_id: Call identifier used in the filename.

        Returns:
            Location of the copied recording.
        """
        self._directory.mkdir(parents=True, exist_ok=True)
        filename = (
            f"{_safe_key_part(conversation_id)}-{_safe_key_part(call_id)}"
            f".{RECORDING_FILE_EXTENSION}"
        )
        destination = self._directory / filename
        shutil.copy2(source, destination)
        return RecordingReference(
            provider="local",
            bucket="",
            key=filename,
            uri=_file_uri(destination),
            content_type=RECORDING_CONTENT_TYPE,
        )


def _file_uri(path: Path) -> str:
    """Return a file:// URI for an absolute filesystem path."""
    return urljoin("file:", pathname2url(str(path)))
